examples.code:
New-OfficeMarkdown -Path .\Notes.md {
    MarkdownHeading 'Release notes'
    MarkdownParagraph 'Version 2.4 is available on the internal feed.'
}

$stopped = Get-Service | Where-Object Status -eq 'Stopped' | Select-Object Name, DisplayName, StartType
New-OfficeMarkdown -Path .\Reports\Stopped-Services.md -Force {
    MarkdownFrontMatter @{ title = 'Stopped services'; generated = (Get-Date -Format 'yyyy-MM-dd') }
    MarkdownHeading 'Stopped services'
    MarkdownParagraph "$($stopped.Count) services are stopped on $env:COMPUTERNAME."
    MarkdownTable -InputObject $stopped
}

$doc = New-OfficeMarkdown
foreach ($server in 'web01', 'web02', 'sql01') {
    Add-OfficeMarkdownHeading -Document $doc -Text $server -Level 2
    Add-OfficeMarkdownParagraph -Document $doc -Text "Last patched: $((Get-Date).ToString('yyyy-MM-dd'))"
}
Save-OfficeMarkdown -Document $doc -Path .\Reports\Patching.md

Open-OfficeMarkdown -Path .\CHANGELOG.md {
    MarkdownHeading '2.4.0 - 2026-10-26' -Level 2
    MarkdownList 'Added CSV export for audit reports', 'Fixed date parsing in weekly summaries'
}

$options = New-OfficeMarkdownReaderOptions -Profile CommonMark -MaxInputCharacters 500000 -DisallowFileUrls -AllowMailtoUrls -RestrictUrlSchemes -AllowedUrlScheme https
Get-ChildItem .\Uploads -Filter *.md | ForEach-Object {
    Get-OfficeMarkdownHeading -LiteralPath $_.FullName -Options $options
}

$sales = Import-OfficeCsv -Path .\Data\Sales.csv
New-OfficeMarkdown -Path .\Reports\Sales-by-Region.md {
    MarkdownHeading 'Sales by region'
    foreach ($region in $sales | Group-Object Region) {
        MarkdownHeading $region.Name -Level 2
        MarkdownTable -InputObject $region.Group
    }
}

New-OfficeMarkdown -Path .\Reports\Backup-Status.md {
    MarkdownHeading 'Backup status'
    MarkdownParagraph {
        MarkdownText 'Overall: ' -Bold
        MarkdownText 'healthy. Details are on the '
        MarkdownText 'backup dashboard' -Link 'https://status.example.com/backups'
        MarkdownText '.'
    }
}

New-OfficeMarkdown -Path .\Docs\Upgrade.md {
    MarkdownHeading 'Upgrade steps'
    MarkdownList -Numbered {
        MarkdownListItem {
            MarkdownText 'Stop the service with '
            MarkdownText 'Stop-Service -Name Spooler' -Code
        }
        MarkdownListItem {
            MarkdownText 'Skip the old '
            MarkdownText 'setup.exe /legacy' -Code -Strikethrough
            MarkdownText ' step; it is '
            MarkdownText 'no longer needed' -Italic
        }
    }
}

$failed = Get-Service | Where-Object { $_.StartType -eq 'Automatic' -and $_.Status -ne 'Running' }
New-OfficeMarkdown -Path .\Reports\Service-Check.md {
    MarkdownHeading 'Automatic services that are not running'
    MarkdownList -Items $failed.DisplayName
    MarkdownHeading 'Next steps' -Level 2
    MarkdownList -Numbered {
        MarkdownListItem 'Check the System event log for each service'
        MarkdownListItem 'Restart the service and confirm it stays running'
        MarkdownListItem 'Open a ticket if it stops again'
    }
}

New-OfficeMarkdown -Path .\Tiers.md {
    MarkdownList {
        MarkdownListItem 'Web tier'
        MarkdownListItem 'Data tier'
    }
}

New-OfficeMarkdown -Path .\Docs\Architecture.md {
    MarkdownHeading 'Components'
    MarkdownList {
        MarkdownListItem {
            MarkdownText 'Web tier' -Bold
            MarkdownList 'web01', 'web02'
        }
        MarkdownListItem {
            MarkdownText 'Data tier' -Bold
            MarkdownList 'sql01 (primary)', 'sql02 (replica)'
        }
    }
}

$steps = @(Import-OfficeCsv -Path .\Data\Migration-Steps.csv)
$done = for ($i = 0; $i -lt $steps.Count; $i++) {
    if ($steps[$i].Status -eq 'Done') { $i + 1 }
}
New-OfficeMarkdown -Path .\Reports\Migration-Checklist.md -Force {
    MarkdownHeading 'Mailbox migration checklist'
    MarkdownTaskList -Items $steps.Step -Completed $done
}

New-OfficeMarkdown -Path .\Processes.md {
    MarkdownTable -InputObject (Get-Process | Select-Object -First 10 Name, Id, CPU)
}

Export-OfficeDocumentImage -Path .\Reports\Q3-Sales.xlsx -Sheet Summary -Chart Revenue -OutputPath .\Reports\revenue.png
New-OfficeMarkdown -Path .\Reports\Q3-Sales.md {
    MarkdownHeading 'Q3 sales'
    MarkdownImage .\revenue.png -Alt 'Revenue by region' -Title 'Q3 revenue' -Width 600px
}

New-OfficeMarkdown -Path .\Maintenance.md {
    MarkdownCallout NOTE 'Maintenance window' 'Servers restart on Saturday at 22:00.'
}

$expiring = Get-ChildItem -Path Cert:\LocalMachine\My | Where-Object NotAfter -lt (Get-Date).AddDays(30)
New-OfficeMarkdown -Path .\Reports\Certificates.md -Force {
    MarkdownHeading 'Certificate review'
    if ($expiring) {
        MarkdownCallout -Kind WARNING -Title 'Renew soon' -Text "$(@($expiring).Count) certificates expire within 30 days."
        MarkdownTable -InputObject ($expiring | Select-Object Subject, NotAfter, Thumbprint)
    } else {
        MarkdownCallout -Kind TIP -Title 'All clear' -Text 'No certificate expires in the next 30 days.'
    }
}

$comments = Import-OfficeCsv -Path .\Data\Survey.csv | Where-Object { [int]$_.Score -ge 9 } | Select-Object -First 3
New-OfficeMarkdown -Path .\Reports\Customer-Voice.md {
    MarkdownHeading 'What customers said'
    foreach ($comment in $comments) {
        MarkdownQuote "$($comment.Comment) ($($comment.Company))"
    }
}

New-OfficeMarkdown -Path .\Build.md {
    MarkdownDetails 'Full build log' {
        MarkdownCode text (Get-Content -Path .\build.log -Raw)
    }
}

$jobs = Get-Content -Path .\Data\nightly-jobs.json -Raw | ConvertFrom-Json
New-OfficeMarkdown -Path .\Reports\Nightly-Jobs.md -Force {
    MarkdownHeading 'Nightly jobs'
    MarkdownTable -InputObject ($jobs | Select-Object Name, Status, Duration)
    foreach ($job in $jobs | Where-Object Status -eq 'Failed') {
        MarkdownDetails "$($job.Name) error output" -Open {
            MarkdownCode -Language text -Text $job.Output
        }
    }
}

New-OfficeMarkdown -Path .\Terms.md {
    MarkdownDefinitionList @{ RPO = 'Recovery point objective'; RTO = 'Recovery time objective' }
}

$terms = [ordered]@{
    SLA = 'Service level agreement: the availability we commit to customers.'
    SLO = 'Service level objective: the internal target that protects the SLA.'
    MTTR = 'Mean time to restore: the average time from incident start to recovery.'
}
New-OfficeMarkdown -Path .\Docs\Glossary.md {
    MarkdownHeading 'Glossary'
    MarkdownDefinitionList -Definition $terms
}

$meta = [ordered]@{
    title = 'October patching summary'
    date = '2026-10-26'
    tags = @('patching', 'windows')
    draft = $false
}
New-OfficeMarkdown -Path .\Site\content\posts\2026-10-26-patching.md {
    MarkdownFrontMatter -InputObject $meta
    MarkdownHeading 'October patching summary'
    MarkdownParagraph '214 servers were patched; 3 need a manual reboot.'
}

New-OfficeMarkdown -Path .\Memo.md {
    MarkdownParagraph 'Summary for the leadership team.'
    MarkdownHorizontalRule
    MarkdownParagraph 'Details for the project team.'
}

$servers = Import-OfficeCsv -Path .\Data\Servers.csv
New-OfficeMarkdown -Path .\Reports\Servers.md {
    MarkdownHeading 'Server inventory'
    foreach ($server in $servers) {
        MarkdownHeading $server.Name -Level 2
        MarkdownTable -InputObject $server -View Transpose
        MarkdownHorizontalRule
    }
}

New-OfficeMarkdown -Path .\Docs\Procedures.md {
    MarkdownHeading 'Procedures' -Level 2
    MarkdownTableOfContents -Section 'Procedures' -Title 'In this section' -TitleLevel 3
    MarkdownHeading 'Failover' -Level 3
    MarkdownHeading 'Restore from backup' -Level 3
}

Get-ChildItem -Path .\Site\content\posts -Filter *.md | Where-Object {
    (Get-OfficeMarkdownFrontMatter -LiteralPath $_.FullName -Key draft).Value -eq $true
} | Select-Object Name, LastWriteTime

Get-ChildItem -Path .\Docs -Filter *.md | ForEach-Object {
    $file = $_.Name
    Get-OfficeMarkdownNode -LiteralPath $_.FullName -NodeType '*Table*' -MaxDepth 2 |
        Select-Object @{ Name = 'File'; Expression = { $file } }, Type, StartLine
}

New-OfficeRtf -Path .\Notes\Change-Notice.rtf {
    RtfParagraph 'Change notice' -Bold -Alignment Center
    RtfParagraph 'The file servers restart on Saturday at 22:00.'
    RtfParagraph 'Save your work before you leave.' -Italic
}

$customers = Import-OfficeCsv -Path .\Data\Customers.csv
foreach ($customer in $customers) {
    $update = @{
        Path = '.\Templates\Welcome.rtf'
        OutputPath = ".\Out\Welcome-$($customer.Id).rtf"
        OldText = '{{CustomerName}}'
        NewText = $customer.Name
        DocumentProperty = @{ Title = "Welcome, $($customer.Name)"; Author = 'Customer Success' }
        DocumentVariable = @{ AccountManager = $customer.Manager }
    }
    Update-OfficeRtfText @update
}

New-OfficeOpenDocument -Path .\Minutes.odt {
    OpenDocumentHeading 'Weekly sync'
    OpenDocumentParagraph 'Decisions and owners from this week.'
}

$sales = Import-OfficeCsv -Path .\Data\Q3-Sales.csv
New-OfficeOpenDocument -Path .\Reports\Q3-Sales.ods {
    OpenDocumentSheet 'Q3' {
        OpenDocumentCell -Row 1 -Column 1 -Value 'Region'
        OpenDocumentCell -Row 1 -Column 2 -Value 'Revenue'
        $row = 2
        foreach ($line in $sales) {
            OpenDocumentCell -Row $row -Column 1 -Value $line.Region
            OpenDocumentCell -Row $row -Column 2 -Value ([decimal]$line.Revenue)
            $row++
        }
    }
}

Open-OfficeOpenDocument -Path .\Minutes.odt {
    OpenDocumentHeading 'Action items' -Level 2
    OpenDocumentParagraph 'Anna: renew the support contract by 15 November.'
    OpenDocumentParagraph 'Tomasz: schedule the failover test.'
}

$departments = Import-OfficeCsv -Path .\Data\Departments.csv
New-OfficeOpenDocument -Path .\Reports\Headcount.odt {
    OpenDocumentHeading 'Headcount by department'
    foreach ($department in $departments) {
        OpenDocumentHeading $department.Name -Level 2
        OpenDocumentParagraph "$($department.Headcount) people, $($department.OpenRoles) open roles."
    }
}

New-OfficeOpenDocument -Path .\Note.odt {
    OpenDocumentParagraph 'The office is closed on 11 November.'
}

New-OfficeOpenDocument -Path .\Reports\Services.odt {
    OpenDocumentHeading 'Stopped services'
    foreach ($service in Get-Service | Where-Object Status -eq 'Stopped') {
        OpenDocumentParagraph "$($service.DisplayName) ($($service.Name))"
    }
}

$orders = Import-OfficeCsv -Path .\Data\Orders.csv
New-OfficeOpenDocument -Path .\Reports\Orders-by-Region.ods {
    foreach ($region in $orders | Group-Object Region) {
        OpenDocumentSheet $region.Name {
            OpenDocumentCell -Row 1 -Column 1 -Value 'Order'
            OpenDocumentCell -Row 1 -Column 2 -Value 'Amount'
            $row = 2
            foreach ($order in $region.Group) {
                OpenDocumentCell -Row $row -Column 1 -Value $order.OrderId
                OpenDocumentCell -Row $row -Column 2 -Value ([decimal]$order.Amount)
                $row++
            }
        }
    }
}

$agenda = Import-OfficeCsv -Path .\Data\Agenda.csv
New-OfficeOpenDocument -Path .\Decks\Town-Hall.odp {
    foreach ($item in $agenda) {
        OpenDocumentSlide $item.Topic {
            OpenDocumentTextBox $item.Topic -Y 1cm -Height 3cm
            OpenDocumentTextBox "Presented by $($item.Owner)" -Y 5cm -Height 2cm
        }
    }
}

New-OfficeOpenDocument -Path .\Decks\Results.odp {
    OpenDocumentSlide 'Results' {
        OpenDocumentTextBox 'Q3 results' -X 2cm -Y 1.5cm -Width 22cm -Height 3cm -Name Title
        OpenDocumentTextBox 'Revenue grew 12% and churn fell to 2.1%.' -X 2cm -Y 6cm -Width 22cm -Height 8cm -Name Summary
    }
}

$disks = Get-CimInstance -ClassName Win32_LogicalDisk -Filter 'DriveType = 3'
New-OfficeOpenDocument -Path .\Reports\Disks.ods {
    OpenDocumentSheet 'Disks' {
        OpenDocumentCell -Row 1 -Column 1 -Value 'Drive'
        OpenDocumentCell -Row 1 -Column 2 -Value 'Free GB'
        OpenDocumentCell -Row 1 -Column 3 -Value 'Checked'
        $row = 2
        foreach ($disk in $disks) {
            OpenDocumentCell -Row $row -Column 1 -Value $disk.DeviceID
            OpenDocumentCell -Row $row -Column 2 -Value ([math]::Round($disk.FreeSpace / 1GB, 1))
            OpenDocumentCell -Row $row -Column 3 -Value (Get-Date)
            $row++
        }
    }
}

New-OfficeEpub -Path .\Guide.epub -Title 'Onboarding guide' {
    EpubChapter 'Welcome' -Text 'Welcome to the team.'
}

$chapters = Get-ChildItem -Path .\Book\chapters -Filter *.md | Sort-Object Name
New-OfficeEpub -Path .\Out\Operations-Handbook.epub -Title 'Operations handbook' -Author 'IT Operations' -Language en {
    EpubResource -Path .\Book\cover.png -Id cover -MediaType image/png
    foreach ($chapter in $chapters) {
        EpubChapter -Title $chapter.BaseName -Markdown (Get-Content -LiteralPath $chapter.FullName -Raw)
    }
}

New-OfficeEpub -Path .\Guide.epub -Title 'Guide' {
    EpubChapter 'Introduction' -Text 'This guide explains how to request access.'
}

New-OfficeEpub -Path .\Out\Security-Guide.epub -Title 'Security guide' -Author 'Security Office' {
    foreach ($file in Get-ChildItem -Path .\Book\security -Filter *.md | Sort-Object Name) {
        $title = (Get-Content -LiteralPath $file.FullName -TotalCount 1).TrimStart('#', ' ')
        EpubChapter -Title $title -Markdown (Get-Content -LiteralPath $file.FullName -Raw)
    }
}

New-OfficeEpub -Path .\Out\Brand-Guide.epub -Title 'Brand guide' {
    EpubResource -Path .\Book\styles\book.css -Id css -MediaType text/css -ContainerPath 'Styles/book.css'
    EpubResource -Path .\Book\fonts\Inter.woff2 -Id inter -MediaType font/woff2 -ContainerPath 'Fonts/Inter.woff2'
    EpubChapter 'Typography' -Markdown (Get-Content -Path .\Book\typography.md -Raw)
}

Get-ChildItem -Path .\Library -Filter *.epub | ForEach-Object {
    $book = Open-OfficeEpub -LiteralPath $_.FullName
    Set-OfficeEpubMetadata -Document $book -Language en-GB -Author 'Evotec Documentation'
    Save-OfficeEpub -Document $book
}

Get-ChildItem -Path .\docs -Filter *.adoc | ForEach-Object {
    $doc = Open-OfficeAsciiDoc -LiteralPath $_.FullName
    Save-OfficeAsciiDoc -Document $doc -Mode Canonical -LineEnding LF
}

$options = New-OfficeAsciiDocReadOptions -MaximumTableCellCount 100000
Get-ChildItem -Path .\Uploads -Filter *.adoc | ForEach-Object {
    $result = Open-OfficeAsciiDoc -LiteralPath $_.FullName -Options $options -AsResult
    [pscustomobject]@{ File = $_.Name; Diagnostics = $result.Diagnostics.Count }
}
